USE threattrace;

CREATE TABLE IF NOT EXISTS investigation_cases(case_id INT PRIMARY KEY AUTO_INCREMENT,case_name VARCHAR(120) NOT NULL,classification VARCHAR(40) NOT NULL,is_synthetic BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS digital_twin_nodes(node_id INT PRIMARY KEY AUTO_INCREMENT,case_id INT NOT NULL,label VARCHAR(120) NOT NULL,node_type VARCHAR(32) NOT NULL,criticality TINYINT NOT NULL CHECK(criticality BETWEEN 1 AND 5),certainty ENUM('OBSERVED','INFERRED','CONFIGURED','UNKNOWN') NOT NULL,FOREIGN KEY(case_id) REFERENCES investigation_cases(case_id),UNIQUE(case_id,label));
CREATE TABLE IF NOT EXISTS event_logs(event_id INT PRIMARY KEY AUTO_INCREMENT,case_id INT NOT NULL,occurred_at DATETIME(3) NOT NULL,event_type ENUM('IDENTITY','PROCESS','NETWORK','FILE','USB','SYSTEM') NOT NULL,source_label VARCHAR(100) NOT NULL,description VARCHAR(500) NOT NULL,evidence_ref VARCHAR(120) NOT NULL,certainty ENUM('OBSERVED','INFERRED','MISSING_TELEMETRY') NOT NULL,host_label VARCHAR(120) NOT NULL,parent_event_id INT NULL,feature_sequence VARCHAR(80) NOT NULL,feature_target VARCHAR(80) NOT NULL,feature_behavior VARCHAR(80) NOT NULL,feature_progression VARCHAR(80) NOT NULL,is_synthetic BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(case_id) REFERENCES investigation_cases(case_id),FOREIGN KEY(parent_event_id) REFERENCES event_logs(event_id),INDEX ix_event_case_time(case_id,occurred_at),INDEX ix_event_type(event_type));
CREATE TABLE IF NOT EXISTS digital_twin_edges(edge_id INT PRIMARY KEY AUTO_INCREMENT,case_id INT NOT NULL,from_node_id INT NOT NULL,to_node_id INT NOT NULL,edge_type VARCHAR(40) NOT NULL,certainty ENUM('OBSERVED','INFERRED','CONFIGURED','UNKNOWN') NOT NULL,description VARCHAR(250) NOT NULL,FOREIGN KEY(case_id) REFERENCES investigation_cases(case_id),FOREIGN KEY(from_node_id) REFERENCES digital_twin_nodes(node_id),FOREIGN KEY(to_node_id) REFERENCES digital_twin_nodes(node_id),CHECK(from_node_id<>to_node_id),INDEX ix_twin_case(case_id));
CREATE TABLE IF NOT EXISTS hypotheses(hypothesis_id INT PRIMARY KEY AUTO_INCREMENT,case_id INT NOT NULL,title VARCHAR(180) NOT NULL,status ENUM('OPEN','SUPPORTED','WEAKENED','REJECTED') NOT NULL DEFAULT 'OPEN',confidence DECIMAL(4,3) NOT NULL CHECK(confidence BETWEEN 0 AND 1),rationale VARCHAR(500) NOT NULL,missing_telemetry VARCHAR(300) NOT NULL,FOREIGN KEY(case_id) REFERENCES investigation_cases(case_id));
CREATE TABLE IF NOT EXISTS hypothesis_evidence(hypothesis_id INT NOT NULL,event_id INT NOT NULL,relation ENUM('SUPPORTS','CONTRADICTS') NOT NULL,note VARCHAR(250) NOT NULL,PRIMARY KEY(hypothesis_id,event_id,relation),FOREIGN KEY(hypothesis_id) REFERENCES hypotheses(hypothesis_id),FOREIGN KEY(event_id) REFERENCES event_logs(event_id));
CREATE TABLE IF NOT EXISTS similarity_comparisons(comparison_id INT PRIMARY KEY AUTO_INCREMENT,case_a INT NOT NULL,case_b INT NOT NULL,overall_score DECIMAL(5,2) NOT NULL,method_version VARCHAR(40) NOT NULL,input_digest CHAR(64) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(case_a) REFERENCES investigation_cases(case_id),FOREIGN KEY(case_b) REFERENCES investigation_cases(case_id),CHECK(case_a<case_b),INDEX ix_similarity_cases(case_a,case_b));
CREATE TABLE IF NOT EXISTS similarity_dimensions(comparison_id INT NOT NULL,dimension ENUM('SEQUENCE','TIMING','TARGET','BEHAVIOR','PROGRESSION') NOT NULL,score DECIMAL(5,2) NOT NULL,explanation VARCHAR(500) NOT NULL,matched_refs JSON NOT NULL,differing_refs JSON NOT NULL,missing_notes JSON NOT NULL,PRIMARY KEY(comparison_id,dimension),FOREIGN KEY(comparison_id) REFERENCES similarity_comparisons(comparison_id));
CREATE TABLE IF NOT EXISTS comparison_input_events(comparison_id INT NOT NULL,side ENUM('A','B') NOT NULL,event_id INT NOT NULL,PRIMARY KEY(comparison_id,side,event_id),FOREIGN KEY(comparison_id) REFERENCES similarity_comparisons(comparison_id),FOREIGN KEY(event_id) REFERENCES event_logs(event_id),INDEX ix_comparison_event(event_id));
CREATE TABLE IF NOT EXISTS mitigation_strategies(strategy_id INT PRIMARY KEY AUTO_INCREMENT,label VARCHAR(120) NOT NULL,risk_reduction TINYINT NOT NULL CHECK(risk_reduction BETWEEN 0 AND 100),business_disruption TINYINT NOT NULL CHECK(business_disruption BETWEEN 0 AND 100),evidence_impact TINYINT NOT NULL CHECK(evidence_impact BETWEEN 0 AND 100),estimated_minutes SMALLINT NOT NULL);
CREATE TABLE IF NOT EXISTS simulation_runs(simulation_id INT PRIMARY KEY AUTO_INCREMENT,case_id INT NOT NULL,scenario_label VARCHAR(120) NOT NULL,model_version VARCHAR(40) NOT NULL,assumptions VARCHAR(500) NOT NULL,output_json JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(case_id) REFERENCES investigation_cases(case_id));
CREATE TABLE IF NOT EXISTS evidence_packages(package_id INT PRIMARY KEY AUTO_INCREMENT,case_id INT NOT NULL,purpose VARCHAR(300) NOT NULL,recipient_label VARCHAR(120) NOT NULL,status ENUM('DRAFT','PENDING_REVIEW','RELEASED','REJECTED','EXPIRED') NOT NULL DEFAULT 'DRAFT',expires_at DATETIME NOT NULL,manifest_hash CHAR(64) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(case_id) REFERENCES investigation_cases(case_id),INDEX ix_package_status(status,expires_at));
CREATE TABLE IF NOT EXISTS package_items(package_id INT NOT NULL,event_id INT NOT NULL,redaction_mode ENUM('PSEUDONYMIZE','GENERALIZE_TIME') NOT NULL,PRIMARY KEY(package_id,event_id),FOREIGN KEY(package_id) REFERENCES evidence_packages(package_id),FOREIGN KEY(event_id) REFERENCES event_logs(event_id));
CREATE TABLE IF NOT EXISTS package_approvals(approval_id INT PRIMARY KEY AUTO_INCREMENT,package_id INT NOT NULL,reviewer_label VARCHAR(120) NOT NULL,decision ENUM('APPROVE','REJECT') NOT NULL,reason VARCHAR(300) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(package_id) REFERENCES evidence_packages(package_id),INDEX ix_approval_package(package_id,decision));
CREATE TABLE IF NOT EXISTS audit_events(audit_id BIGINT PRIMARY KEY AUTO_INCREMENT,case_id INT NOT NULL,object_type VARCHAR(40) NOT NULL,object_id INT NOT NULL,action VARCHAR(40) NOT NULL,actor_label VARCHAR(120) NOT NULL,reason VARCHAR(300) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(case_id) REFERENCES investigation_cases(case_id),INDEX ix_audit_case_time(case_id,created_at));

CREATE OR REPLACE VIEW vw_case_timeline AS SELECT e.event_id,e.case_id,e.occurred_at,e.event_type,e.source_label,e.description,e.evidence_ref,e.certainty,e.host_label,e.parent_event_id FROM event_logs e;
CREATE OR REPLACE VIEW vw_similarity_explanation AS SELECT c.comparison_id,c.case_a,c.case_b,c.overall_score,c.method_version,d.dimension,d.score,d.explanation,d.matched_refs,d.differing_refs,d.missing_notes FROM similarity_comparisons c JOIN similarity_dimensions d ON d.comparison_id=c.comparison_id;
CREATE OR REPLACE VIEW vw_asset_exposure AS SELECT e.case_id,n.node_id,n.label,n.node_type,n.criticality,n.certainty,e.certainty event_certainty,e.event_type,e.event_id FROM digital_twin_nodes n JOIN event_logs e ON e.case_id=n.case_id AND (e.host_label=n.label OR e.feature_target=n.node_type);
CREATE OR REPLACE VIEW vw_package_review AS SELECT p.package_id,p.case_id,p.purpose,p.recipient_label,p.status,p.expires_at,pi.event_id,pi.redaction_mode,a.reviewer_label,a.decision FROM evidence_packages p LEFT JOIN package_items pi ON pi.package_id=p.package_id LEFT JOIN package_approvals a ON a.package_id=p.package_id;
CREATE OR REPLACE VIEW vw_audit_history AS SELECT audit_id,case_id,object_type,object_id,action,actor_label,reason,created_at FROM audit_events;

DELIMITER $$
DROP TRIGGER IF EXISTS trg_event_parent_insert_guard$$
CREATE TRIGGER trg_event_parent_insert_guard AFTER INSERT ON event_logs FOR EACH ROW
BEGIN IF NEW.parent_event_id IS NOT NULL AND NEW.parent_event_id=NEW.event_id THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='An event cannot be its own parent'; END IF; END$$
DROP TRIGGER IF EXISTS trg_event_parent_update_guard$$
CREATE TRIGGER trg_event_parent_update_guard BEFORE UPDATE ON event_logs FOR EACH ROW
BEGIN IF NEW.parent_event_id IS NOT NULL AND NEW.parent_event_id=NEW.event_id THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='An event cannot be its own parent'; END IF; END$$
DROP TRIGGER IF EXISTS trg_package_status_audit$$
CREATE TRIGGER trg_package_status_audit AFTER UPDATE ON evidence_packages FOR EACH ROW
BEGIN IF OLD.status<>NEW.status THEN INSERT INTO audit_events(case_id,object_type,object_id,action,actor_label,reason) VALUES(NEW.case_id,'PACKAGE',NEW.package_id,CONCAT('STATUS_',NEW.status),'workflow','Package status transition'); END IF; END$$
DROP TRIGGER IF EXISTS trg_package_release_guard$$
CREATE TRIGGER trg_package_release_guard BEFORE UPDATE ON evidence_packages FOR EACH ROW
BEGIN IF NEW.status='RELEASED' AND OLD.status<>'RELEASED' AND NOT EXISTS(SELECT 1 FROM package_approvals WHERE package_id=OLD.package_id AND decision='APPROVE') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Release requires reviewer approval'; END IF; END$$
DROP TRIGGER IF EXISTS trg_redaction_audit$$
CREATE TRIGGER trg_redaction_audit AFTER INSERT ON package_items FOR EACH ROW
BEGIN INSERT INTO audit_events(case_id,object_type,object_id,action,actor_label,reason) SELECT case_id,'PACKAGE',NEW.package_id,'EVIDENCE_SELECTED','workflow',CONCAT('Event ',NEW.event_id,' redaction mode ',NEW.redaction_mode) FROM evidence_packages WHERE package_id=NEW.package_id; END$$
DROP PROCEDURE IF EXISTS sp_submit_package_for_review$$
CREATE PROCEDURE sp_submit_package_for_review(IN p_id INT)
BEGIN IF NOT EXISTS(SELECT 1 FROM package_items WHERE package_id=p_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Package needs at least one evidence item'; END IF; UPDATE evidence_packages SET status='PENDING_REVIEW' WHERE package_id=p_id AND status='DRAFT'; IF ROW_COUNT()<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Package must be in DRAFT status'; END IF; END$$
DROP PROCEDURE IF EXISTS sp_approve_package_release$$
CREATE PROCEDURE sp_approve_package_release(IN p_id INT)
BEGIN IF NOT EXISTS(SELECT 1 FROM package_approvals WHERE package_id=p_id AND decision='APPROVE') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Approval record required'; END IF; UPDATE evidence_packages SET status='RELEASED' WHERE package_id=p_id AND status='PENDING_REVIEW'; IF ROW_COUNT()<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Package must be pending review'; END IF; END$$
DROP PROCEDURE IF EXISTS sp_expire_packages$$
CREATE PROCEDURE sp_expire_packages()
BEGIN UPDATE evidence_packages SET status='EXPIRED' WHERE status IN ('DRAFT','PENDING_REVIEW','RELEASED') AND expires_at<UTC_TIMESTAMP(); END$$
DROP PROCEDURE IF EXISTS sp_record_simulation_run$$
CREATE PROCEDURE sp_record_simulation_run(IN p_case INT,IN p_label VARCHAR(120),IN p_assumptions VARCHAR(500),IN p_output JSON)
BEGIN INSERT INTO simulation_runs(case_id,scenario_label,model_version,assumptions,output_json) VALUES(p_case,p_label,'twin-1.0',p_assumptions,p_output); END$$
DELIMITER ;
